package com.domesticservice.booking.service;
import com.domesticservice.booking.repository.support.NativeQueryExecutor;import com.domesticservice.booking.repository.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import tools.jackson.databind.ObjectMapper;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="DISCIPLINE_POSTGRES_VERIFY",matches="true")
@SpringBootTest(classes=ForgottenJobPostgresTests.Config.class,webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:postgresql://localhost:5549/discipline_booking","spring.datasource.username=postgres","spring.datasource.password=discipline_test_only","spring.jpa.hibernate.ddl-auto=none","spring.flyway.enabled=true"})
class ForgottenJobPostgresTests {
 @Configuration(proxyBeanMethods=false) @EnableAutoConfiguration @Import({NativeQueryExecutor.class,BookingOperationsSqlRepository.class,BookingWorkflowSqlRepository.class,BookingWorkflowService.class}) static class Config {
  @Bean(destroyMethod="stop") Peer peer(ObjectMapper json)throws Exception{return new Peer(json);}
  @Bean BookingOperationsService ops(BookingOperationsSqlRepository repo,ObjectMapper json,Peer p){return new BookingOperationsService(repo,json,p.url(),p.url());}
  @Bean ForgottenJobService jobs(NativeQueryExecutor db,PlatformTransactionManager tx,org.springframework.beans.factory.ObjectProvider<BookingWorkflowService> flow,Peer p){return new ForgottenJobService(db,tx,flow,p.url(),p.url(),"isolated-test-key");}
 }
 static class Peer {final HttpServer server;volatile boolean fail;Peer(ObjectMapper json)throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{var path=x.getRequestURI().getPath();Object reply=path.endsWith("policy")?Map.of("no_show_enabled",true,"grace_minutes",0,"effective_from",Instant.now().minusSeconds(86400).toString()):path.endsWith("recovery-vouchers")?Map.of("promotion_code","ISOLATED-5"):path.endsWith("no-show")?Map.of("id",1):path.endsWith("refund")?Map.of("status","RECONCILED","refundedAmount",10000):Map.of("id",x.getRequestHeaders().getFirst("Authorization").contains("other")?102:101,"role","CUSTOMER");var bytes=json.writeValueAsBytes(reply);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(fail&&!path.endsWith("policy")?503:200,bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();}String url(){return "http://127.0.0.1:"+server.getAddress().getPort();}public void stop(){server.stop(0);}}
 @Autowired JdbcTemplate db;@Autowired ForgottenJobService jobs;@Autowired BookingWorkflowService flow;@Autowired Peer peer;@Autowired PlatformTransactionManager manager;long booking,assignment;
 @BeforeEach void init(){peer.fail=false;booking=db.queryForObject("INSERT INTO bookings(booking_code,booking_mode,status,customer_id,service_id,address_id,service_snapshot,address_snapshot,starts_at,ends_at,required_staff_count,base_amount,total_amount,payment_method,pricing_confirmed) VALUES (?,'MODE_B','CONFIRMED',101,1,1,'{}','{}',?,?,1,10000,10000,'CASH',true) RETURNING id",Long.class,"fault-test-"+UUID.randomUUID(),Timestamp.from(Instant.now().minusSeconds(60)),Timestamp.from(Instant.now().plusSeconds(3600)));assignment=db.queryForObject("INSERT INTO booking_assignments(booking_id,staff_id,status,execution_status,accepted_at) VALUES (?,201,'ACCEPTED','ACCEPTED',now()) RETURNING id",Long.class,booking);}
 @Test void forgottenJobCancelsOnlyOnceAndPersistsRetryableRemediation(){peer.fail=true;jobs.scan();assertEquals("CANCELLED",db.queryForObject("SELECT status FROM bookings WHERE id=?",String.class,booking));assertEquals(1,db.queryForObject("SELECT count(*) FROM forgotten_job_remediations WHERE booking_id=?",Integer.class,booking));assertFalse(db.queryForObject("SELECT finance_synced FROM forgotten_job_remediations WHERE booking_id=?",Boolean.class,booking));peer.fail=false;jobs.scan();jobs.deliver();assertTrue(db.queryForObject("SELECT finance_synced AND voucher_synced AND refund_synced FROM forgotten_job_remediations WHERE booking_id=?",Boolean.class,booking));assertEquals(1,db.queryForObject("SELECT count(*) FROM staff_execution_events WHERE booking_id=?",Integer.class,booking));}
 @Test void enRouteAndStartedJobsAreNotCancelled(){db.update("UPDATE booking_assignments SET execution_status='EN_ROUTE' WHERE id=?",assignment);jobs.scan();assertEquals("CONFIRMED",db.queryForObject("SELECT status FROM bookings WHERE id=?",String.class,booking));}
 @Test void deadlineCannotBeEvadedByLateDeparture(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->jobs.checkDeparture(db.queryForMap("SELECT * FROM bookings WHERE id=?",booking)));}
 @Test void exactExecutionTimesAreImmutableAndVisibleToOwner(){new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(s->jobs.record(booking,assignment,201,"EN_ROUTE","STAFF","Started travelling"));assertTrue(flow.history("Bearer customer",booking).stream().anyMatch(r->"EN_ROUTE".equals(r.get("status"))));assertThrows(Exception.class,()->db.update("DELETE FROM staff_execution_events WHERE booking_id=?",booking));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->flow.history("Bearer other",booking));}
 @Test void complaintsEnforceOwnershipAndIdempotency(){var b=Map.<String,Object>of("reason","Isolated complaint","requestKey","complaint-"+booking,"staffId",201);var first=flow.incident("Bearer customer",booking,b);assertEquals(first,flow.incident("Bearer customer",booking,b));assertEquals(1,flow.incidents("Bearer customer",booking).size());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->flow.incident("Bearer other",booking,b));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->flow.incident("Bearer customer",booking,Map.of("reason","wrong staff","requestKey","other-"+booking,"staffId",999)));}
}
